// ---------- Ayudas ----------
export function engagedWith(s, u) {
  return s.units.filter((e) => e.models > 0 && e.owner !== u.owner && unitDist(u, e) < 0.12);
}
export const isEngaged = (s, u) => engagedWith(s, u).length > 0;
const logE = (ev, msg, extra = {}) => { const e = { msg, ...extra }; ev.push(e); return e; };
const logE0 = logE;

function inForest(s, p) { return s.terrain.some((t) => t.kind === 'forest' && inRect(p, t)); }
// Edificios (Core p.273-276): una unidad de infantería que pueda alcanzarlo en su movimiento lo ocupa; cobertura pesada, visión de 360°, sin flancos, se le carga como obstáculo defendido, sin bonificación por filas, no persigue
const u0 = (s, a) => byId(s, a.id);
// Edificios de Dawn of the Storm Dragon (p.): ocupables si miden 4" o más en su punto más ancho (o son una torre especial); infantería con US 20 o menos (torre: US 10 o menos, o un personaje de infantería)
