const fearLd = (s, u, src) => { const b = psyLd(s, u) - (src && darkAura(src) ? 1 : 0); /* Core p.274 Aura oscura: -1 Ld por el Miedo/Terror que causa quien ocupa unas ruinas oscuras */ if (bannersOf(u).some((x) => x.godsBan)) return b; const maj = s.units.some((h) => h.owner !== u.owner && h.models > 0 && !h.fleeing && [h, ...joinedLive(h)].some((m) => (m.items || []).includes('dark_majesty') && cmdIn(h, u, m))); return maj ? Math.max(2, b - 1) : b; }; // Majestad Oscura: −1 Ld a los chequeos de Miedo y Terror
const despairOf = (e) => [e, ...(e.joined || [])].some((m) => m.models > 0 && D(m).sr.includes('heraldDespair'));
const despair = (s, e, [a, b]) => { if (!despairOf(e)) return [a, b]; const c = d6(s); const lo = Math.min(a, b, c); const v = [a, b, c]; v.splice(v.indexOf(lo), 1); return v; };
