const gloamF = (e, t) => { const g = fx(t, 'gloaming'); return !!g && e.owner === g.by && !e.merc && e.owner !== t.owner; };
// Ruinas oscuras (Core p.274): Aura oscura y ocupación
const darkBld = (u) => !!CUR && !!u.garrison && CUR.terrain.some((t) => t.id === u.garrison && t.dark);
const darkAura = (src) => darkBld(src) && causesFear(src);
const darkImm = (u) => darkBld(u) && !causesFear(u); // si no causa Miedo ni Terror, es inmune a ambos
const terrorTo = (e, t) => has(e, 'terror') || (gloamF(e, t) && has(e, 'fear'));
const isElf = (x) => ['he', 'de', 'wood'].includes(D(x).faction) && !['we_dryads', 'we_dryads_amb', 'we_treekin', 'we_treekin_amb', 'we_treeman', 'we_treeman_amb', 'we_ancient', 'we_branchwraith', 'he_eagle', 'we_eagle', 'de_harpies'].includes(x.type) && (D(x).cat === 'char' || !['monCreature', 'behemoth', 'warBeasts', 'swarm'].includes(D(x).tt)); // v838 Miedo a los Elfos (rh.txt:1956-1958): «Elves of any type cause Fear in models with this special rule» — Altos Elfos, Elfos Oscuros y Elfos Silvanos (antes solo Silvanos); quedan fuera los espíritus del bosque y las bestias/monstruos sin dotación élfica
