    const ii = [u, ...(u.joined || [])].find((x) => x.models > 0 && itemsOf(x).some((i) => i.impactIt));
    let imp = riderPass ? (ii && !fx(u, 'incorp') ? { ...itemsOf(ii).find((i) => i.impactIt).impactIt, S: D(ii).S } : null) : fx(u, 'incorp') ? null : ((u.allyList ?? s.lists?.[u.owner]) === 'nomad' && (u.type === 'boar_riders') ? { n: '1', S: 3, ap: 1, perModel: true } : (u.allyList ?? s.lists?.[u.owner]) === 'nomad' && D(u).cat === 'char' && D(u).mount && D(u).sr.includes('tusker') ? { n: '1', S: 3, ap: 1 } : null) || D(u).impact || (hb ? { n: '1', S: D(hb).S, ap: 2 } : null) || (ii ? { ...itemsOf(ii).find((i) => i.impactIt).impactIt, S: D(ii).S } : null) || (bannersOf(u).some((b) => b.impact1) && D(u).cat !== 'mach' ? { n: '1', S: D(u).S, ap: 0, perModel: true } : null);
    if (imp && D(u).tt === 'heavyChar') imp = { ...imp, ap: Math.max(imp.ap || 0, 2) }; // Ruedas con guadañas (Core p.195): los Impactos de un carro pesado tienen Perforación -2
