    if (u.std && D(u).cat !== 'char' && u.models > 0 && !u.fleeing) std = Math.max(std, 1 + (ITEMS[u.banner]?.cr || 0) /* v838: el +D3 de los estandartes con «+D3 al resultado de combate» se suma una sola vez, en el bucle de objetos de resolución (antes también aquí: doble D3) */ + (ITEMS[u.banner]?.virulence ? Math.min(3, u.poisonU || 0) : 0) + (ITEMS[u.banner]?.crForest && s.terrain.some((t) => t.kind === 'forest' && rectDist(u, t) <= 6) ? 1 : 0));
    if (u.models > 0 && !u.fleeing && !bsbCR && [u, ...joinedLive(u)].some(isBSB)) { bsbCR = true; bsbPt = 1 + [u, ...joinedLive(u)].filter(isBSB).reduce((t, c) => t + (ITEMS[c.banner]?.cr || 0), 0); }
    if (u.models > 0 && waaaghOn(u) && !wg) { wg = true; std += 1; }
