  if (mine.some((u) => u.models > 0 && s.units.some((b) => b.models > 0 && b.owner === side && !b.fleeing && [b, ...joinedLive(b)].some((m) => m.models > 0 && ITEMS[m.banner]?.stromni && cmdIn(b, u, m))))) co += 1;
