  const ovk = Math.min(5, mine.reduce((t, u) => t + (u.overkill || 0), 0)) + (mine.some((u) => u.models > 0 && u.chargeOK && [u, ...joinedLive(u)].some((m) => D(m).sr.includes('trophyRack'))) ? 1 : 0);
