export const commandRange = (c) => (/^ct_(magistrate|strategist)_lantern/.test(c.type) ? 12 : c.banner === 'b_tapestry' || D(c).sr.includes('settraGreat') ? 18 : (D(c).general || isBSB(c)) ? (has(c, 'large') ? 18 : 12) : D(c).sr.includes('symbolMight') ? Math.max(12, cmdLd(c)) : cmdLd(c)) /* Símbolo de poder (Altar de Guerra, FoF): 12" */ + (D(c).sr.includes('commandVoice') ? 3 : 0) + (itemsOf(c).some((i) => i.cmdR3) ? 3 : 0); // Core p.205: General y PEB 12" (18" si grandes); Tapiz de Talsyn 18"
