  if (ok) for (const f of alive(s, p).filter((x) => D(x).faction === 'lm' && (x.id === t.id || unitDist(x, t) <= 7))) { f.fx = (f.fx || []).filter((q) => q.k !== 'primR'); f.fx.push({ k: 'primR', by: p, endTurn: true }); }
