      if (u.marched || u.fleeing || u.dirgeK === turnKey(s)) return fail('No puede usar el Lamento');
      if (unitDist(u, t) > 8) return fail('Objetivo fuera de alcance (8")');
      u.dirgeK = turnKey(s);
