// ---------- Consultas para UI/IA ----------
export function legalShootTargets(s, u) {
  if (!rangedOf(u)) return [];
  return alive(s, 1 - u.owner).filter((e) => !shootCheck(s, u, e));
}
export function canAct(s, u) {
  if (u.models <= 0 || u.owner !== s.active) return false;
  if (s.phase === 'move') return (!u.moved || (!u.charged && !u.marched && bannersOf(u).some((b) => b.rakaph) && u.rakaphT !== s.turn + ':' + s.active)) && !u.fleeing && !u.stupid && !isEngaged(s, u);
  if (s.phase === 'shoot') return legalShootTargets(s, u).length > 0 || ((!!D(u).wizard || (u.items || []).includes('ring_ruin') || boundIts(u).some((i) => i.boundSpell) || !!u.scintSpell) && !u.fleeing && !isEngaged(s, u) && spellKeys(u).some((k) => SPELLS[k].type === 'missile' && !u.casted.includes(k)));
  if (s.phase === 'strategy') return !!D(u).wizard && !u.fleeing && !u.noMore && !isEngaged(s, u) && spellKeys(u).some((k) => ['hex', 'enchant'].includes(SPELLS[k].type) && !u.casted.includes(k));
  return false;
}
// ¿Puede esta unidad participar en la fase actual? { can, txt }: txt = qué puede hacer o el motivo por el que no puede (situación de esta ronda y fase)
export function phaseInfo(s, u) {
  if (!u || u.models <= 0 || ['deploy', 'over'].includes(s.phase)) return null;
  const eng = isEngaged(s, u);
  if (s.phase === 'combat') {
    if (!eng) return { can: false, txt: 'No está trabada en combate' };
    if (u.fought) return { can: false, txt: 'Ya ha peleado en esta ronda' };
    return { can: true, txt: 'Puede pelear (trabada en combate)' };
  }
  if (u.owner !== s.active) return { can: false, txt: 'No es su turno' };
  const base = u.fleeing ? 'Está huyendo' : u.stupid ? 'Estupidez: no puede actuar' : null;
  if (s.phase === 'move') {
    if (eng) return { can: false, txt: 'Trabada en combate: no puede mover' };
    if (base) return { can: false, txt: base };
    if (u.moved && !canAct(s, u)) return { can: false, txt: u.charged ? 'Ya ha cargado' : u.marched ? 'Ya ha marchado' : 'Ya ha movido' };
    return { can: true, txt: 'Puede mover, marchar o cargar' };
  }
  if (s.phase === 'shoot') {
    const tg = legalShootTargets(s, u).length > 0, sp = canAct(s, u);
    if (tg || sp) return { can: true, txt: [tg ? 'Puede disparar' : null, sp && !tg ? 'Puede lanzar proyectiles mágicos' : null].filter(Boolean).join(' · ') };
    if (eng) return { can: false, txt: 'Trabada en combate: no dispara' };
    if (base) return { can: false, txt: base };
    if (!rangedOf(u)) return { can: false, txt: 'Sin arma de proyectiles ni hechizos de proyectil' };
    if (u.shot) return { can: false, txt: 'Ya ha disparado' };
    const why = alive(s, 1 - u.owner).map((e) => shootCheck(s, u, e)).find(Boolean);
    return { can: false, txt: why || 'Sin enemigos a tiro' };
  }
  if (s.phase === 'strategy') {
    if (!D(u).wizard) return { can: false, txt: 'No lanza hechizos' };
    if (eng) return { can: false, txt: 'Trabada en combate: no lanza' };
    if (base) return { can: false, txt: base };
    if (u.noMore) return { can: false, txt: 'No puede lanzar más hechizos' };
    return canAct(s, u) ? { can: true, txt: 'Puede lanzar hechizos' } : { can: false, txt: 'Sin hechizos que lanzar ahora' };
  }
  return null;
}
